<template>
  <details class="conference-panel">
    <summary>{{ tr('Eventos de conferencia','Conference events') }}</summary>
    <p>{{ tr('Bloquean el horario al guardarse. Publica después de consultar con el pastor; no requieren aprobación de ExCom. Editar un evento lo retira de publicación hasta publicarlo de nuevo. Si coinciden con eventos de departamentos, se solicitarán cambios y se retirarán de publicación.', 'These block time immediately. Publish after consulting the pastor; ExCom approval is not required. Editing unpublishes an event until you publish it again. Overlapping department events will require changes and be unpublished.') }}</p>
    <p v-if="message" role="status">{{ message }}</p><p v-if="error" role="alert" class="text-danger">{{ error }}</p>
    <div class="creation-heading"><h3>{{ tr('Evento de conferencia','Conference event') }}</h3><button type="button" :class="editorOpen ? 'btn btn-outline-secondary' : 'creation-plus'" :disabled="busy" :aria-expanded="editorOpen" :aria-label="editorOpen ? tr('Cancelar','Cancel') : tr('Crear evento de conferencia','Create conference event')" @click="editorOpen ? reset() : editorOpen=true">{{ editorOpen ? tr('Cancelar','Cancel') : '+' }}</button></div><form v-if="editorOpen" @submit.prevent="save"><fieldset :disabled="busy"><div class="fields"><label>{{ tr('Título de conferencia','Conference title') }}<input v-model="form.title" required maxlength="255" /></label><label>{{ tr('Lugar','Location') }}<input v-model="form.location" maxlength="255" /></label><label>{{ tr('Inicio de conferencia','Conference start') }}<input v-model="form.start_at" type="datetime-local" required /></label><label>{{ tr('Fin de conferencia','Conference end') }}<input v-model="form.end_at" type="datetime-local" required /></label></div><label>{{ tr('Descripción','Description') }}<textarea v-model="form.description" rows="2"></textarea></label><div class="actions"><button class="btn btn-primary">{{ form.id ? tr('Actualizar conferencia','Update conference') : tr('Crear evento de conferencia','Create conference event') }}</button><button v-if="form.id" class="btn btn-outline-secondary" type="button" @click="reset">{{ tr('Cancelar edición','Cancel edit') }}</button></div></fieldset></form>
    <div class="csv"><h3>{{ tr('Importar CSV','Import CSV') }}</h3><p>{{ tr('Columnas: title,start_at,end_at,description,location. Fechas ISO con zona horaria (ejemplo: 2026-12-01T09:00:00-05:00). Se validan todas las filas antes de guardar; los eventos idénticos se omiten.', 'Columns: title,start_at,end_at,description,location. ISO dates with timezone (example: 2026-12-01T09:00:00-05:00). All rows are validated before saving; identical events are skipped.') }}</p><label>{{ tr('Archivo CSV de conferencia','Conference CSV file') }}<input type="file" accept=".csv,text/csv" :disabled="busy" @change="file=$event.target.files[0]" /></label><button class="btn btn-outline-primary" :disabled="busy || !file" @click="upload">{{ tr('Importar conferencia','Import conference') }}</button></div>
    <button class="btn btn-outline-success" :disabled="busy" @click="publish()">{{ tr('Publicar todos los eventos de conferencia','Publish all conference events') }}</button>
    <article v-for="event in events.filter(e=>e.is_conference_event && e.status !== 'cancelled')" :key="event.id"><div><strong>{{ event.title }}</strong><span> · {{ event.publish_to_feed ? tr('Publicado','Published') : tr('No publicado','Unpublished') }}</span><p>{{ new Date(event.start_at).toLocaleString(locale) }}</p></div><div class="actions"><button class="btn btn-outline-success" :disabled="busy" @click="publish(event)">{{ event.publish_to_feed ? tr('Retirar de publicación','Unpublish') : tr('Publicar evento','Publish event') }}</button><button class="btn btn-outline-secondary" :disabled="busy" @click="edit(event)" :aria-expanded="editorOpen && form.id===event.id">{{ editorOpen && form.id===event.id ? tr('Cancelar','Cancel') : tr('Editar','Edit') }}</button><button class="btn btn-outline-danger" :disabled="busy" @click="cancel(event)">{{ tr('Cancelar evento','Cancel event') }}</button></div></article>
  </details>
</template>
<script setup>
import {ref} from 'vue'
import {apiClient} from '../services/authApi'
const props=defineProps({churchId:Number,locale:{type:String,default:'es'},events:{type:Array,default:()=>[]}}),emit=defineEmits(['changed'])
const tr=(es,en)=>props.locale==='es'?es:en
const editorOpen=ref(false)
const blank=()=>({title:'',location:'',description:'',start_at:'',end_at:''}),form=ref(blank()),busy=ref(false),error=ref(''),message=ref(''),file=ref(null)
const local=v=>{const d=new Date(v);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
function reset(){form.value=blank();editorOpen.value=false}
function edit(e){if(editorOpen.value && form.value.id===e.id){reset();return}editorOpen.value=true;form.value={id:e.id,title:e.title,location:e.location||'',description:e.description||'',start_at:local(e.start_at),end_at:local(e.end_at)}}
async function run(action){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await action();emit('changed')}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||tr('No se pudo guardar.','Could not save.')}finally{busy.value=false}}
async function save(){await run(async()=>{const payload={...form.value,church_id:props.churchId,start_at:new Date(form.value.start_at).toISOString(),end_at:new Date(form.value.end_at).toISOString()};await(form.value.id?apiClient.patch(`/conference-events/${form.value.id}`,payload):apiClient.post('/conference-events',payload));reset();message.value=tr('Evento de conferencia guardado.','Conference event saved.')})}
async function upload(){await run(async()=>{const data=new FormData();data.append('file',file.value);data.append('church_id',props.churchId);const result=await apiClient.post('/conference-events/import',data);message.value=tr(`Creados: ${result.data.created}. Omitidos: ${result.data.skipped}.`,`Created: ${result.data.created}. Skipped: ${result.data.skipped}.`)})}
async function publish(e){await run(async()=>{await apiClient.post(e?`/conference-events/${e.id}/publish`:'/conference-events/publish-all',{church_id:props.churchId,published:e?!e.publish_to_feed:true});message.value=tr('Publicación actualizada.','Publication updated.')})}
async function cancel(e){await run(async()=>{await apiClient.delete(`/conference-events/${e.id}`,{params:{church_id:props.churchId}});if(form.value.id===e.id)reset();message.value=tr('Evento cancelado. Los departamentos pueden usar el horario libre.','Event cancelled. Departments can use the released time.')})}
</script>
<style scoped>
.conference-panel{background:#fff;border:1px solid #dadfe8;border-radius:10px;padding:16px;margin-bottom:18px;font-size:12px;min-width:0}.conference-panel summary{font-size:14px;font-weight:500;cursor:pointer}.conference-panel p{color:#667080;margin:10px 0;overflow-wrap:anywhere}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.conference-panel label{display:block}.conference-panel input,.conference-panel textarea{display:block;width:100%;min-width:0;margin-top:5px;padding:8px;border:1px solid #d8dee5;border-radius:5px}.conference-panel fieldset{border:0;padding:0;display:grid;gap:12px}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{width:auto;font-size:12px}.csv{border-top:1px solid #e4e8ed;margin-top:18px;padding-top:14px}.csv h3{font-size:14px}.csv .btn{margin-top:10px}article{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;border-top:1px solid #e4e8ed;padding-top:12px;margin-top:12px}@media(max-width:600px){.fields{grid-template-columns:1fr}}
</style>
